class Solution(object):
    def maxProduct(self, s):
        """
        :type s: str
        :rtype: int
        """
        n = len(s)
        valid = []
        for i in range(1, 1 << n):
            cur_s = ""
            for j in range(n):
                if i & (1 << j) != 0:
                    cur_s += s[j]
            if cur_s == cur_s[::-1]:
                valid.append(i)

        def count(num):
            ans = 0
            for i in range(n):
                if num & (1 << i) != 0:
                    ans += 1
            return ans

        ans = 0
        for i in range(len(valid)):
            for j in range(i, len(valid)):
                if valid[i] & valid[j] == 0:
                    ans = max(ans, count(valid[i]) * count(valid[j]))
        return ans
